import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;

public class Main {
    public static void main(String[] args) {
        Map<String, Integer> marks = new HashMap<>();
        marks.put("Ali", 70);
        marks.put("Sara", 95);
        marks.put("Ali", 75);                    // replaces the old value
        System.out.println(marks.get("Ali"));
        System.out.println(marks.getOrDefault("Omar", 0));
        System.out.println(marks.containsKey("Sara") + " " + marks.size());

        for (Map.Entry<String, Integer> e : new TreeMap<>(marks).entrySet()) {
            System.out.println(e.getKey() + " -> " + e.getValue());
        }
    }
}
